"""Hand-checked targeted cases for boundary rules in the contract."""
import sys, json
sys.path.insert(0,'/workspace/dev'); sys.path.insert(0,'/workspace/submission'); sys.path.insert(0,'/workspace/site')
import ctypes; ctypes.CDLL('/workspace/native/libz.so.1', mode=ctypes.RTLD_GLOBAL)
import harness; harness.setup_env()
import reference, formats, pipeline, discovery
norm = lambda o: json.dumps(o, sort_keys=True, separators=(',',':'))


def release(rid='m', classes=2, width=2, eps=(1,1), ratio=(0,1), threshold=(1,1),
            mode='range', packet_limit=None, idle_us=10**9, discovery_rows=None,
            train=None, validation=None):
    return {'id': rid, 'classes': classes, 'width': width,
            'eps': list(eps), 'ratio': list(ratio), 'threshold': list(threshold),
            'mode': mode, 'packet_limit': packet_limit if packet_limit is not None else width,
            'idle_us': idle_us, 'discovery': discovery_rows or [],
            'train': train or [], 'validation': validation or []}


def row(cls, values, acts=None):
    if acts is None:
        acts = [5] * len(values)
    return {'class': cls, 'values': list(values), 'activation': list(acts)}


def vrow(cls, values):
    return {'class': cls, 'values': list(values)}


def run(request, label, expect=None):
    try:
        mine = pipeline.execute(formats.validate(json.loads(json.dumps(request))))
    except Exception as exc:
        mine = 'INVALID ' + repr(exc)
    try:
        theirs = reference.execute(request)
    except Exception as exc:
        theirs = 'INVALID'
    same = (isinstance(mine, str) == isinstance(theirs, str)) and \
           (not isinstance(mine, str) or mine.startswith('INVALID') == theirs.startswith('INVALID'))
    if not isinstance(mine, str) and not isinstance(theirs, str):
        same = norm(mine) == norm(theirs)
    verdict = 'AGREE' if same else 'DIFF'
    extra = ''
    if expect is not None:
        ok = json.dumps(mine, sort_keys=True).replace('"', '') == \
             json.dumps(expect, sort_keys=True).replace('"', '') if not isinstance(mine, str) else False
        extra = ' EXPECT_OK' if (isinstance(mine, dict) and norm(mine) == norm(expect)) or \
                                (isinstance(mine, str) and isinstance(expect, str) and
                                 mine.split()[0] == expect) else ' EXPECT_DIFF'
    print(label, verdict + extra)
    if verdict == 'DIFF' or (expect is not None and 'EXPECT_DIFF' in extra):
        print('  mine', json.dumps(mine, sort_keys=True)[:1200])
        print('  ref ', json.dumps(theirs, sort_keys=True)[:1200])
        if expect is not None:
            print('  exp ', json.dumps(expect, sort_keys=True)[:1200])
    return mine
